sys_variable_value.value:
(function execute(inputs, outputs) {

var utils = new EventUtils();
    var eventGR = utils.getEventDetails(inputs.eventid);

    if (eventGR) {
        outputs.name = eventGR.name;
        outputs.date = eventGR.event_date;
        outputs.vip = eventGR.isvip;
        outputs.status = eventGR.status;
    } else {
        outputs.name = '';
        outputs.date = '';
        outputs.vip = false;
        outputs.status = '';
    }


})(inputs, outputs);

