sys_variable_value.value:
(function execute(inputs, outputs) {

var utils = new EventUtils();
    var eventGR = utils.getEventDetails(inputs.eventid);

    if (eventGR) {
        outputs.name = eventGR.getDisplayValue('x_event_name');
        outputs.date = eventGR.getDisplayValue('x_event_date');
        outputs.vip = eventGR.getValue('x_is_vip') == 'true';
        outputs.status = eventGR.getDisplayValue('x_status');
    } else {
        outputs.name = '';
        outputs.date = '';
        outputs.vip = false;
        outputs.status = '';
    }


})(inputs, outputs);

